    });

    const res = await t.fetch("/custom/file v2.xyz?query=123");
    expect(res.headers.get("content-type")).toBe("application/custom");
    expect(customOptions.getType).toHaveBeenCalledWith(".xyz");

    const res2 = await t.fetch("/custom/file.txt");
    expect(res2.headers.get("content-type")).toBe("text/plain");

    const res3 = await t.fetch("/custom/file");
    expect(res3.headers.get("content-type")).toBe(
      t.target === "web" ? null : "text/plain; charset=UTF-8",
    );
  });

  it("resolves the MIME type of an uppercase extension", async () => {
    const res = await t.fetch("/photos/IMG_0001.JPG");
    expect(res.headers.get("content-type")).toBe("image/jpeg");
  });

  it("uses the requested asset's MIME type for a precompressed variant", async () => {
    const files: Record<string, string> = {
      "/pre/app.js": "js",
      "/pre/app.js.gz": "js.gz",
      "/pre/app.js.br": "js.br",
      "/pre/style.css.gz": "css.gz",
      "/pre/docs/index.html.br": "html.br",
    };
    const options: ServeStaticOptions = {
      getContents: vi.fn((id) => files[id]),
      getMeta: vi.fn((id) => (files[id] ? { size: files[id].length } : undefined)),
      encodings: { gzip: ".gz", br: ".br" },
    };

    t.app.all("/pre/**", (event) => {
      return serveStatic(event, options);
    });

    for (const [path, acceptEncoding, body, type] of [
      ["/pre/app.js", "gzip", "js.gz", "text/javascript"],
      ["/pre/app.js", "br, gzip;q=0.5", "js.br", "text/javascript"],
      ["/pre/app.js", "identity", "js", "text/javascript"],
      ["/pre/style.css", "gzip", "css.gz", "text/css"],
      ["/pre/docs", "br", "html.br", "text/html"],
    ] as const) {
      const res = await t.fetch(path, { headers: { "accept-encoding": acceptEncoding } });
      expect(await res.text(), `${path} (${acceptEncoding})`).toBe(body);
      expect(res.headers.get("content-type"), `${path} (${acceptEncoding})`).toBe(type);
    }
  });

  it("does not overwrite a content-length already set on the response", async () => {
    // An explicit response content-length must win over the size derived from
    // meta — consistent with content-type / content-encoding / last-modified,
    // which are only set when not already present on the response.
    const options: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 18 })),
      headers: { "content-length": "999" },
    };

    t.app.all("/clen/**", (event) => {
      return serveStatic(event, options);
    });

    const res = await t.fetch("/clen/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("999");
  });

  it("serves .wasm as application/wasm", async () => {
    // `WebAssembly.instantiateStreaming()` rejects any other type
    const res = await t.fetch("/module.wasm");
    expect(res.headers.get("content-type")).toBe("application/wasm");
  });
});

describe("serve static (malformed url)", () => {
  it("falls through on a malformed `%` instead of throwing", async () => {
    // With `allowMalformedURL`, a raw malformed `%` (e.g. `/foo%`) reaches
    // serveStatic and the final `decodeURI` would throw a URIError — a 500 that
    // bypasses `fallthrough`. The guarded decode falls back to the resolved id
    // so `fallthrough` (and 404 when off) are reached as normal.
    const options: ServeStaticOptions = {
      getContents: () => undefined,
      getMeta: () => undefined,
    };

    const fallthroughApp = new H3({ allowMalformedURL: true })
      .use((event) => serveStatic(event, { ...options, fallthrough: true }))
      .use(() => "next");
    const res = await fallthroughApp.request("/foo%");
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");

    const notFoundApp = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, options),
    );
    const res404 = await notFoundApp.request("/foo%");
    expect(res404.status).toBe(404);
  });

  it("never hands a raw backslash or bare `..` to the backend under allowMalformedURL", async () => {
    // Defense-in-depth guard for the trickiest input we could construct: a
    // malformed `%` (forcing the raw pathname) whose segment is popped by a
    // `..`, leaving single-encoded `%5c` separators. If the on-disk decode
    // (`%5c` → `\`) were not neutralized, the id would become
    // `/..\..\windows\win.ini` — a traversal above the root on backslash-aware
    // (e.g. Windows) filesystem backends. It is neutralized because serveStatic
    // re-resolves dot segments *after* that decode. The event layer cannot help
    // here: canonicalization never decodes a separator (and is skipped entirely
    // for a malformed path), so `%5c` reaches serveStatic in its wire form.
    let servedId: string | undefined;
    const app = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, {
        getContents: (id) => {
          servedId = id;
          return `asset:${id}`;
        },
        getMeta: () => ({ size: 1 }),
      }),
    );

    const res = await app.request("/a%ZZ/../..%5c..%5cwindows%5cwin.ini");
    expect(res.status).toBe(200);
    expect(servedId).toBeDefined();
    expect(servedId).not.toContain("\\"); // no raw backslash separator
    expect(servedId).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/); // no bare `..` segment
  });
});

describeMatrix("serve static range", (t, { it, expect }) => {
  const mtime = 1_700_000_000_000;
  const lastModified = new Date(mtime).toUTCString();
  const bytes = new TextEncoder().encode("0123456789");

  let body: () => any;
  let meta: (id: string) => any;
  let getContents: ReturnType<typeof vi.fn>;
  let extra: Partial<ServeStaticOptions>;

  beforeEach(() => {
    body = () => "0123456789";
    extra = {};
    meta = (id) =>
      id.includes("404")
        ? undefined
        : { type: "text/plain", etag: '"abc"', mtime, size: id.endsWith(".gz") ? 20 : 10 };
    getContents = vi.fn((id: string) => (id.endsWith(".gz") ? "0123456789abcdefghij" : body()));
    t.app.all("/**", (event) =>
      serveStatic(event, {
        getContents: (id) => getContents(id),
        getMeta: (id) => meta(id),
        ...extra,
      }),
    );
  });

  const each =
    (rows: any[]) =>
    (name: string, fn: (...args: any[]) => any): void => {
      rows.forEach((row, i) =>
        it(`${name} #${i}`, () => fn(...(Array.isArray(row) ? row : [row]))),
      );
    };

  const get = (range: string | undefined, headers: Record<string, string> = {}, method = "GET") =>
    t.fetch("/file.txt", {
      method,
      headers: { ...(range === undefined ? {} : { range }), ...headers },
    });

  it("advertises accept-ranges on 200 (GET/HEAD)", async () => {
    const res = await get(undefined);
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("0123456789");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-length")).toBe("10");
    const head = await get(undefined, {}, "HEAD");
    expect(head.status).toBe(200);
    expect(head.headers.get("accept-ranges")).toBe("bytes");
  });

  each([
    ["bytes=2-5", "2345", "bytes 2-5/10"],
    ["bytes=7-", "789", "bytes 7-9/10"],
    ["bytes=-3", "789", "bytes 7-9/10"],
    ["bytes=8-99", "89", "bytes 8-9/10"],
    ["bytes=-50", "0123456789", "bytes 0-9/10"],
    ["bytes=0-0", "0", "bytes 0-0/10"],
    ["BYTES=2-5", "2345", "bytes 2-5/10"],
    [" bytes = 2 - 5 ", "2345", "bytes 2-5/10"],
    ["bytes=0-99999999999999999999999", "0123456789", "bytes 0-9/10"],
  ])("serves %s as 206", async (range, text, contentRange) => {
    const res = await get(range);
    expect(res.status).toBe(206);
    expect(await res.text()).toBe(text);
    expect(res.headers.get("content-range")).toBe(contentRange);
    expect(res.headers.get("content-length")).toBe(String(text.length));
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("etag")).toBe('"abc"');
  });

  it("HEAD with range sends only headers", async () => {
    const res = await get("bytes=2-5", {}, "HEAD");
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("");
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(getContents).not.toHaveBeenCalled();
  });

  each(["GET", "HEAD"])("%s unsatisfiable range is 416", async (method) => {
    for (const range of ["bytes=10-20", "bytes=-0", "bytes=99-"]) {
      const res = await get(range, {}, method);
      expect(res.status).toBe(416);
      expect(res.headers.get("content-range")).toBe("bytes */10");
      expect(res.headers.get("content-length")).toBe("0");
      expect(res.headers.get("etag")).toBe('"abc"');
      expect(await res.text()).toBe("");
    }
    expect(getContents).not.toHaveBeenCalled();
  });

  each([
    "bytes=abc",
    "bytes=5-2",
    "bytes=",
    "bytes=-",
    "bytes=0-1,4-5",
    "items=0-1",
    "bytes=5abc-6",
    "bytes=-1-2",
  ])("ignores %s", async (range) => {
    const res = await get(range);
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("0123456789");
    expect(res.headers.get("content-range")).toBeNull();
  });

  each([
    ['"abc"', 206],
    ['"other"', 200],
    ['W/"abc"', 200],
    [lastModified, 206],
    [new Date(mtime + 5000).toUTCString(), 200],
  ])("If-Range %s -> %i", async (ifRange, status) => {
    const res = await get("bytes=0-3", { "if-range": ifRange as string });
    expect(res.status).toBe(status);
    expect(await res.text()).toBe(status === 206 ? "0123" : "0123456789");
  });

  it("If-Range without validator or without Range gives 200", async () => {
    meta = () => ({ size: 10 });
    expect((await get("bytes=0-3", { "if-range": '"abc"' })).status).toBe(200);
    meta = () => ({ size: 10, etag: '"abc"' });
    expect((await get(undefined, { "if-range": '"abc"' })).status).toBe(200);
  });

  it("cache conditionals win over range", async () => {
    const a = await get("bytes=0-3", { "if-none-match": '"abc"' });
    expect(a.status).toBe(304);
    expect(await a.text()).toBe("");
    const b = await get("bytes=0-3", { "if-modified-since": lastModified });
    expect(b.status).toBe(304);
  });

  it("applies range to the precompressed variant and keeps headers", async () => {
    extra = {
      encodings: { gzip: ".gz" },
      headers: { "cache-control": "public" },
    };
    meta = (id) => ({
      type: "text/plain",
      etag: '"abc"',
      mtime,
      size: id.endsWith(".gz") ? 20 : 10,
      // Unknown label so the node client does not try to gunzip the fake body.
      encoding: id.endsWith(".gz") ? "x-test" : undefined,
    });
    const res = await get("bytes=0-9", { "accept-encoding": "gzip" });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("0123456789");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/20");
    for (const [k, v] of Object.entries({
      "content-encoding": "x-test",
      vary: "accept-encoding",
      etag: '"abc"',
      "last-modified": lastModified,
      "content-type": "text/plain",
      "cache-control": "public",
    })) {
      expect(res.headers.get(k)).toBe(v);
    }
    const bad = await get("bytes=20-", { "accept-encoding": "gzip" });
    expect(bad.status).toBe(416);
    expect(bad.headers.get("content-range")).toBe("bytes */20");
    expect(bad.headers.get("vary")).toBe("accept-encoding");
    expect(bad.headers.get("cache-control")).toBe("public");
  });

  const stream = (chunks: Uint8Array[], onCancel?: () => void) =>
    new ReadableStream<Uint8Array>({
      start(c) {
        for (const chunk of chunks) c.enqueue(chunk);
        c.close();
      },
      cancel: onCancel,
    });

  each([
    ["string", () => "0123456789"],
    ["Uint8Array", () => bytes.slice()],
    ["ArrayBuffer", () => bytes.slice().buffer],
    ["Blob", () => new Blob(["0123456789"])],
    ["File", () => new File(["0123456789"], "a.txt")],
    ["stream (1 chunk)", () => stream([bytes.slice()])],
    [
      "stream (chunks)",
      () => stream([bytes.slice(0, 1), bytes.slice(1, 3), bytes.slice(3, 7), bytes.slice(7)]),
    ],
  ])("slices %s body", async (_name, make) => {
    body = make;
    const res = await get("bytes=2-5");
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
    expect(res.headers.get("content-length")).toBe("4");
  });

  it("slices multibyte strings by bytes", async () => {
    body = () => "éé345678";
    meta = () => ({ size: 10, etag: '"abc"' });
    const res = await get("bytes=2-3");
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("é");
  });

  it("cancels the upstream stream after the range", async () => {
    const onCancel = vi.fn();
    body = () => stream([bytes.slice(0, 4), bytes.slice(4)], onCancel);
    const res = await get("bytes=1-2");
    expect(await res.text()).toBe("12");
    await new Promise((r) => setTimeout(r, 10));
    expect(onCancel).toHaveBeenCalled();
  });

  each([undefined, 0])("ignores range without known size (%s)", async (size) => {
    meta = () => ({ size });
    const res = await get("bytes=0-3");
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("0123456789");
    expect(res.headers.get("accept-ranges")).toBeNull();
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("keeps 404 and 405 with range", async () => {
    const res = await t.fetch("/404.txt", { headers: { range: "bytes=0-3" } });
    expect(res.status).toBe(404);
    t.errors.length = 0;
    const post = await t.fetch("/file.txt", { method: "POST", headers: { range: "bytes=0-3" } });
    expect(post.status).toBe(405);
    t.errors.length = 0;
  });

  it("overrides preset content-length only for 206/416", async () => {
    extra = { headers: { "content-length": "999" } };
    expect((await get(undefined)).headers.get("content-length")).toBe("999");
    expect((await get("bytes=2-5")).headers.get("content-length")).toBe("4");
    expect((await get("bytes=50-")).headers.get("content-length")).toBe("0");
  });
});

